    // Function implementation
}

function addFlowLimiter(address flowLimiter) external onlyRole(uint8(Roles.OPERATOR)) override {
    // Function implementation
}

function addFlowOut(uint256 amount) external onlyService override {
    // Function implementation
}

function addFlowIn(uint256 amount) external onlyService override {
    // Function implementation
}

function getTokenAddressFromParams(bytes calldata params_) external pure override returns (address tokenAddress_) {
    // Function implementation
}

function implementationType() external pure override returns (uint256) {
    // Function implementation
}

function interchainTokenId() public pure override returns (bytes32) {
